#include <algorithm>
#include <array>
#include <ctime>
#include <fstream>
#include <iostream>
#include <map>
#include <set>
#include <sstream>
#include <stdexcept>
#include <string>
#include <vector>
using namespace std;
constexpr int N=1250,NN=1254,L0=1250,L1=1251,L2=1252,C=1253;
using Adj=array<array<int,3>,NN>;
Adj src,a;vector<pair<int,int>>edges;clock_t startcpu;double limitcpu;
struct B{array<int,NN>d,par;int ecc;};
double cpu(){return double(clock()-startcpu)/CLOCKS_PER_SEC;}
string ints(vector<int>p){ostringstream o;o<<'[';for(size_t i=0;i<p.size();i++){if(i)o<<',';o<<p[i];}o<<']';return o.str();}
B bfs(int r){B b;b.d.fill(-1);b.par.fill(-1);array<int,NN>q;int lo=0,hi=0;q[hi++]=r;b.d[r]=0;b.ecc=0;while(lo<hi){int u=q[lo++];for(int v:a[u])if(b.d[v]<0){b.d[v]=b.d[u]+1;b.par[v]=u;b.ecc=max(b.ecc,b.d[v]);q[hi++]=v;}}if(hi<NN)b.ecc=NN;return b;}
int bad(const B&b){for(int t=0;t<NN;t++)if(b.d[t]<0||b.d[t]>10)return t;return -1;}
vector<int>path(const B&b,int r,int t){vector<int>p;if(b.d[t]<0)return p;for(int v=t;v>=0;v=b.par[v]){p.push_back(v);if(v==r)break;}reverse(p.begin(),p.end());return p;}
void rem1(int u,int v){for(int&x:a[u])if(x==v){x=-1;return;}throw runtime_error("missingcut");}
void rem(int u,int v){rem1(u,v);rem1(v,u);}
void add1(int u,int v){for(int&x:a[u])if(x<0){x=v;return;}throw runtime_error("noport");}
void add(int u,int v){add1(u,v);add1(v,u);}
bool adj(int u,int v){return find(a[u].begin(),a[u].end(),v)!=a[u].end();}
void build(int g,int h){a=src;for(int u=N;u<NN;u++)a[u].fill(-1);rem(0,1);rem(869,1178);rem(g,h);add(L0,0);add(L0,1);add(L1,869);add(L1,1178);add(L2,g);add(L2,h);for(int l:{L0,L1,L2})add(C,l);for(int u:{0,1,869,1178,g,h,L0,L1,L2,C}){set<int>s;for(int v:a[u])if(v<0||v>=NN||v==u||!s.insert(v).second||!adj(v,u))throw runtime_error("candidatecubic/simple");}if(!adj(L0,C)||!adj(C,L1)||!adj(L1,1178))throw runtime_error("P1walkbroken");}
string role(int u,int v){if(u==C||v==C)return"helper_star";if(u>=N||v>=N)return"retained_endpoint_spoke";return"retained_source";}
void witness(string file,int eid,int g,int h,string stage,int root,int target,const B&b){ofstream o(file);auto p=path(b,root,target);o<<"{\"third_edge_id\":"<<eid<<",\"third_cut\":["<<g<<','<<h<<"],\"stage\":\""<<stage<<"\",\"root\":"<<root<<",\"target\":"<<target<<",\"distance\":"<<b.d[target]<<",\"path\":"<<ints(p)<<",\"edge_roles\":[";for(size_t i=1;i<p.size();i++){if(i>1)o<<',';o<<'"'<<role(p[i-1],p[i])<<'"';}o<<"]}\n";}
void hitfiles(int eid,int g,int h,vector<pair<int,int>>&stats){ofstream e("candidate1254.edges");e<<NN<<" 1881\n";for(int u=0;u<NN;u++)for(int v:a[u])if(u<v)e<<u<<' '<<v<<'\n';ofstream p("PARAMETERS.json");p<<"{\"n\":1254,\"m\":1881,\"degree\":3,\"fixed_cuts\":[[0,1],[869,1178]],\"third_edge_id\":"<<eid<<",\"third_cut\":["<<g<<','<<h<<"],\"helper_labels\":{\"L0\":1250,\"L1\":1251,\"L2\":1252,\"centre\":1253},\"spokes\":[[1250,0],[1250,1],[1251,869],[1251,1178],[1252,"<<g<<"],[1252,"<<h<<"]],\"helper_edges\":[[1253,1250],[1253,1251],[1253,1252]],\"status\":\"ALLROOT_PASS_PENDING_FRESH_ACCEPTANCE\"}\n";ofstream s("ALL_ROOT_STATS.tsv");s<<"root\teccentricity\n";for(auto v:stats)s<<v.first<<'\t'<<v.second<<'\n';}
int main(int argc,char**argv){startcpu=clock();limitcpu=argc>2?stod(argv[2]):15.;try{ifstream f(argv[1]);int n,m;if(!(f>>n>>m)||n!=N||m!=1875)throw runtime_error("sourceheader");for(auto&r:src)r.fill(-1);for(int i=0;i<m;i++){int u,v;if(!(f>>u>>v)||u<0||v<0||u>=N||v>=N||u==v)throw runtime_error("sourceedge");if(u>v)swap(u,v);edges.push_back({u,v});for(auto z:{make_pair(u,v),make_pair(v,u)}){bool ok=false;for(int&x:src[z.first])if(x<0){x=z.second;ok=true;break;}if(!ok)throw runtime_error("sourcedegree>3");}}sort(edges.begin(),edges.end());if(unique(edges.begin(),edges.end())!=edges.end())throw runtime_error("duplicatedsourceedge");for(int u=0;u<N;u++){for(int v:src[u])if(v<0)throw runtime_error("sourcedegree<3");sort(src[u].begin(),src[u].end());}if(edges[0]!=make_pair(0,1)||edges[1515]!=make_pair(869,1178))throw runtime_error("literalcutbinding");set<int>pins={0,1,869,1178};vector<int>domain;for(int i=0;i<m;i++)if(!pins.count(edges[i].first)&&!pins.count(edges[i].second))domain.push_back(i);ofstream dm("ACTUAL_DOMAIN.json");dm<<"{\"configs\":"<<domain.size()<<",\"source_parse_count\":1,\"source_D10_validity_BFS\":0,\"simple_cubic_input_contract\":true,\"new_n\":1254,\"new_m\":1881,\"orientation_factor\":1}\n";dm.close();ofstream rows("CONFIG_RESULTS.tsv");rows<<"third_edge_id\tg\th\tP1_actual_walk_length\tcentre_ecc\tL0_ecc\tL1_ecc\tL2_ecc\tL0_to_1178_if_tested\tfirst_bad_stage\troot\ttarget\tdistance\n";array<long long,4>calls{},fails{};array<bool,4>have{};long long visited=0,oldbfs=0,fourpass=0,oldfails=0,p1=0;bool found=false,timed=false,first=false;int partial=-1;for(int eid:domain){if(cpu()>limitcpu){timed=true;partial=eid;break;}auto[g,h]=edges[eid];build(g,h);p1++;array<int,4>ecc;ecc.fill(-2);int ld=-2,fr=-1,ft=-1,fd=-1;string stage="";bool pass=true;vector<pair<int,int>>stats;int kk=0;for(int r:{C,L0,L1,L2}){B b=bfs(r);calls[kk]++;ecc[kk]=b.ecc;stats.push_back({r,b.ecc});if(r==L0)ld=b.d[1178];int t=bad(b);if(t>=0){fails[kk]++;pass=false;fr=r;ft=t;fd=b.d[t];stage=(kk==0?"CENTRE":kk==1?"L0":kk==2?"L1":"L2");if(!have[kk]){witness("FIRST_"+stage+"_FAILURE.json",eid,g,h,stage,r,t,b);have[kk]=true;}if(!first){witness("FIRST_FAILURE.json",eid,g,h,stage,r,t,b);first=true;}break;}kk++;}if(pass){fourpass++;for(int r=0;r<N;r++){if(cpu()>limitcpu){timed=true;partial=eid;pass=false;stage="BUDGET_DURING_OLDROOTS";break;}B b=bfs(r);oldbfs++;stats.push_back({r,b.ecc});int t=bad(b);if(t>=0){pass=false;oldfails++;stage="OLD_OLD";fr=r;ft=t;fd=b.d[t];if(oldfails==1)witness("FIRST_OLDOLD_FAILURE.json",eid,g,h,stage,r,t,b);break;}}if(pass){found=true;stage="ALLROOT_PASS";hitfiles(eid,g,h,stats);}}
rows<<eid<<'\t'<<g<<'\t'<<h<<"\t3";for(int v:ecc)rows<<'\t'<<v;rows<<'\t'<<ld<<'\t'<<stage<<'\t'<<fr<<'\t'<<ft<<'\t'<<fd<<'\n';visited++;if(found||timed)break;}
rows.close();ofstream o("NUMERIC_RESULT.json");o<<"{\"status\":\""<<(found?"FOUND_PENDING_FRESH_ACCEPTANCE":timed?"UNKNOWN_BUDGET":"COMPLETE_NO_FIXED_TWO_CUTS_FOURHELPER_STAR")<<"\",\"domain_configs\":"<<domain.size()<<",\"visited_configs\":"<<visited<<",\"partial_or_next_edge_id\":"<<partial<<",\"P1_actual_length3_walk_verified\":"<<p1<<",\"newroot_calls_centre_L0_L1_L2\":["<<calls[0]<<','<<calls[1]<<','<<calls[2]<<','<<calls[3]<<"],\"newroot_firstfails_centre_L0_L1_L2\":["<<fails[0]<<','<<fails[1]<<','<<fails[2]<<','<<fails[3]<<"],\"all_four_newroot_pass\":"<<fourpass<<",\"modified_oldroot_BFS\":"<<oldbfs<<",\"oldold_failed_candidates\":"<<oldfails<<",\"source_parse_count\":1,\"source_D10_validity_BFS\":0,\"native_CPU\":"<<cpu()<<",\"hit\":"<<(found?"true":"false")<<"}\n";cout<<"configs "<<visited<<'/'<<domain.size()<<" fourpass "<<fourpass<<" oldfail "<<oldfails<<" CPU "<<cpu()<<'\n';return 0;}catch(const exception&e){ofstream o("NUMERIC_ERROR.txt");o<<e.what()<<'\n';cerr<<e.what()<<'\n';return 2;}}
